            display_order?: number;
            description?: string | null;
            icon?: string | null;
            color?: string | null;
            custom_icon_svg?: string | null;
            /**
             * Format: int64
             * @description Unix timestamp
             */
            created_at?: number;
            /** @description `text`, `voice`, `forum`, `banner` or `spawner`. Always `text` for categories. On hubs with the `channels.voice` capability only a `voice` channel can be joined for voice; it has a chat as well, and a spawner's rooms are `voice`. */
            channel_type?: string;
            /** @description Omitted unless set */
            banner_url?: string;
            /** @description Omitted unless set */
            banner_file_id?: string;
            /** @description True for a join-to-create room spawned from a spawner channel. */
            is_temporary?: boolean;
            /** @description Temp channels only (omitted otherwise) — the joiner who owns the room. */
            owner_pubkey?: string;
            /** @description Spawner channels only (omitted otherwise) — the name template for spawned rooms. */
            spawner_name_template?: string;
            /** @description Auto-spawned squad rooms only (omitted otherwise) — the event the room was made for. */
            event_id?: string;
            /** @description Forum channels — posts must carry at least one tag. Always false elsewhere. */
            forum_require_tag?: boolean;
            /** @description NSFW flag for this channel specifically */
            nsfw?: boolean;
            /** @description The caller's own `voice.move_members` on this channel, resolved channel-scoped, so a move-destination picker can offer only the channels that will accept the move (events.md §7.1). Advertised as the `channels.move.targets` capability; absent on hubs that do not advertise it, which is not the same as `false`. */
            can_move_members?: boolean;
